      const item = applyMessage(store, raw);
70→      expect(item.outcome).toBe("sin-producto");
      stores.push(item.parsed?.store);
    }
    expect(stores).toEqual(["amazon", "mercadolibre", "ebay", "alibaba", "homecenter"]);
    store.close();
  });

  test("Alibaba con Tracking pending no trae guía y no se inventa una", () => {
    const raw = `From: notice@alibaba.com
Subject: Order update
80→
Alibaba order 998877665544332 is being prepared.
Tracking: pending, it will be shared when the parcel leaves the warehouse.
`;
    expect(parseDispatchEmail(raw)).toEqual({ error: "El correo no trae una guía." });
  });
});

